package com.example.starter.roaming.config;

import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 统一时钟配置，业务时间均以 UTC 为准；测试可替换为可控时钟。
 */
@Configuration
public class ClockConfig {

    @Bean
    public Clock utcClock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.roaming.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.Instant;

/**
 * 即插即充授权请求：以车辆证书指纹标识车辆。
 *
 * @param requestId      业务幂等键
 * @param certFingerprint 车辆证书指纹
 * @param pileNo         桩编号
 * @param requestTime    请求时刻（UTC）
 */
public record AuthorizeRequest(
        @NotBlank String requestId,
        @NotBlank String certFingerprint,
        @NotBlank String pileNo,
        @NotNull Instant requestTime) {
}

package com.example.starter.roaming.api;

import jakarta.validation.constraints.NotBlank;
import java.time.Instant;

/**
 * 会话启动请求。
 * 正常流程携带 sessionNo 承接已授权会话；并发直启场景可携带证书指纹、桩编号与启动时刻（UTC）。
 *
 * @param requestId       业务幂等键
 * @param sessionNo       授权返回的会话号（可空）
 * @param certFingerprint 车辆证书指纹（直启时必填）
 * @param pileNo          桩编号（直启时必填）
 * @param startTime       启动时刻（UTC，直启时必填）
 */
public record StartSessionRequest(
        @NotBlank String requestId,
        String sessionNo,
        String certFingerprint,
        String pileNo,
        Instant startTime) {
}

package com.example.starter.roaming.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.Instant;

/**
 * 会话结束请求。
 *
 * @param requestId 业务幂等键
 * @param endTime   结束时刻（UTC），决定清分归属日
 */
public record EndSessionRequest(
        @NotBlank String requestId,
        @NotNull Instant endTime) {
}

package com.example.starter.roaming.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;
import java.math.BigDecimal;
import java.time.Instant;

/**
 * 计量快照上传请求；快照按“会话号＋抄表序号”去重，乱序按抄表序号归位。
 *
 * @param requestId   业务幂等键
 * @param readingSeq  抄表序号（非负，递增）
 * @param energyKwh   该序号电表累计读数（kWh，非负）
 * @param recordedAt  桩端计量时刻（UTC）
 */
public record MeterSnapshotRequest(
        @NotBlank String requestId,
        @NotNull Integer readingSeq,
        @NotNull @PositiveOrZero BigDecimal energyKwh,
        @NotNull Instant recordedAt) {
}

package com.example.starter.roaming.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.LocalDate;

/**
 * 清分日封存请求：按 UTC 日冻结当日已结束会话并生成清分单。
 *
 * @param requestId     业务幂等键
 * @param settlementDay 清分日（UTC）
 */
public record SealBatchRequest(
        @NotBlank String requestId,
        @NotNull LocalDate settlementDay) {
}

package com.example.starter.roaming.api;

import jakarta.validation.constraints.NotBlank;

/**
 * 差异挂账人工核销请求（须留痕，同一挂账只允许核销一次）。
 *
 * @param requestId    业务幂等键
 * @param operatorName 核销操作人
 * @param remark       核销备注（可空）
 */
public record WriteOffRequest(
        @NotBlank String requestId,
        @NotBlank String operatorName,
        String remark) {
}

