                    Timestamp.from(row.recordedAt()), row.requestId(), Timestamp.from(row.createdAt()));
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    public Optional<SnapshotRow> find(String sessionNo, Integer readingSeq) {
