        return jdbc.query(
                "SELECT id, session_no, reading_seq, energy_kwh, recorded_at_utc, request_id, created_at_utc "
                        + "FROM meter_snapshot WHERE session_no = ? ORDER BY reading_seq",
                MAPPER, sessionNo);
    }

