final class MoneyUtil {

    private MoneyUtil() {
    }

    /** 电量×单价后的金额按四舍五入保留到分。 */
    static BigDecimal yuan(BigDecimal amount) {
        return amount.setScale(2, RoundingMode.HALF_UP);
    }
}

